select.where:
del_flag ='0'

    AND INSTR(machine_code, #{machineCode}) > 0


    AND instr(machine_name, #{machineName} )>0

and status = #{status}
and type = #{type}
and machine_type = #{machineType}

del_flag ='0'

    AND  machine_code = #{machineCode}


    AND instr(machine_name, #{machineName} )>0

and status = #{status}
and type = #{type}
and machine_type = #{machineType}

del_flag ='0'
and id != #{id}
and machine_code = #{machineCode}
and machine_name = #{machineName}

mapper.update:
update t_cx_machine_info
machine_name = #{machineName}, type = #{type}, dimension_minimum = #{dimensionMiniMum,jdbcType=DECIMAL}, dimension_maximum = #{dimensionMaxiMum,jdbcType=DECIMAL}, quata = #{quata}, quota_ratio = #{quotaRatio}, class_shift = #{classShift}, open_machine_class1 = #{openMachineClass1}, open_machine_class2 = #{openMachineClass2}, open_machine_class3 = #{openMachineClass3}, operator_qty = #{operatorQty,jdbcType=DECIMAL}, status = #{status}, remark = #{remark,jdbcType=VARCHAR}, MACHINE_TYPE = #{machineType}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}

select.if:
select a.MACHINE_CODE,b.MACHINE_NAME from T_cx_SPECIFY_MACHINE a
inner JOIN T_CX_MACHINE_INFO b on a.MACHINE_CODE=b.MACHINE_CODE and b.STATUS = '0'
where a.DEL_FLAG='0' and a.JOB_TYPE='0' and a.EMBRYO_CODE=#{machineCode,jdbcType=VARCHAR}
and a.SAP_CODE=#{machineName,jdbcType=VARCHAR}
order by a.MACHINE_CODE,a.create_time desc

select a.MACHINE_CODE,a.MACHINE_NAME from T_CX_MACHINE_INFO a
where a.DEL_FLAG='0' and a.STATUS='0'
and a.MACHINE_CODE not in (
select MACHINE_CODE from T_cx_SPECIFY_MACHINE where DEL_FLAG='0' and JOB_TYPE='0'
and EMBRYO_CODE=#{machineCode,jdbcType=VARCHAR}
and SAP_CODE=#{machineName,jdbcType=VARCHAR}
)
and a.machine_type = #{machineType}
order by a.MACHINE_NAME,a.create_time desc

mapper.select:
select sm.MACHINE_CODE,mi.MACHINE_NAME,sm.JOB_TYPE as type from T_LH_SPECIFY_MACHINE sm,T_LH_MACHINE_INFO mi
where  sm.MACHINE_CODE=mi.MACHINE_CODE and sm.DEL_FLAG='0' and  mi.STATUS = '0' and mi.DEL_FLAG='0'
 and sm.SAP_CODE = #{machineName}
 and sm.MACHINE_CODE = #{machineCode}
 and sm.JOB_TYPE = #{type}
